-- Pashto draft, module 1. Preserve Dutch, Dari, media, order and grading.
-- Source checked against production on 2026-09-13. Native review still required.
BEGIN;
CREATE TEMP TABLE mt_pashto_module_01 ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($ps$[{"n":1,"nl":"Rijbewijs en kenteken","title":"د موټر چلولو جواز او د موټر د ثبت شمېره","summary":"ستاسو د موټر چلولو جواز ټاکي چې کوم ډول موټر چلولای شئ؛ د ثبت شمېره موټر پېژني.","rule":"یوازې هغه موټر وچلوئ چې ستاسو جواز ورته اعتبار لري، او وګورئ چې موټر په سمه توګه ثبت او بیمه شوی وي.","tip":"د چلوونکي جواز د موټر د ثبت له سند سره مه ګډوئ.","question":"کوم سند ښيي چې تاسو د کومو ډولونو موټرو د چلولو اجازه لرئ؟","options":["د موټر چلولو جواز","د موټر د ثبت سند","د APK تخنیکي معاینې لیک"],"explanation":"د موټر چلولو جواز هغه کټګورۍ ښيي چې تاسو یې د چلولو اجازه لرئ."},{"n":2,"nl":"Controlelampjes","title":"د خبرداري څراغونه","summary":"د خبرداري سور څراغ ښايي دا معنا ولري چې باید په خوندي ډول ودرېږئ او انجن بند کړئ.","rule":"د خبرداري سور څراغ مه نادیده کوئ. کله چې خوندي وي، ودرېږئ، د موټر لارښود وګورئ او علت یې وڅېړئ.","tip":"رنګ او نښه معنا ټاکي: سور عموماً سمدستي اقدام او ژېړ ژر کتنې ته اړتیا ښيي.","question":"د چلولو پر مهال د تېلو د فشار سور څراغ بل پاتې کېږي. څه کوئ؟","options":["تر راتلونکي تېل اچولو پورې تګ ته دوام ورکوئ","په خوندي ډول درېږئ او انجن بندوئ","یوازې راډیو بندوئ"],"explanation":"د تېلو د فشار سور څراغ چې بل پاتې شي، ښايي د انجن د سخت زیان نښه وي؛ خوندي ودرېږئ او انجن بند کړئ."},{"n":3,"nl":"Banden en profiel","title":"ټایرونه او د ټایر د نقش ژوروالی","summary":"د سپرلۍ موټر ټایرونه باید کافي نقش ولري؛ قانون لږ تر لږه 1,6 ملي‌متره ژوروالی غواړي.","rule":"ټول ټایرونه د نقش ژوروالي، چاودونو، پړسوبونو او نابرابر سایېدو له پلوه وګورئ.","tip":"نقش په اصلي نالیو کې اندازه کړئ او د زړو ټایرونو د بدلولو لپاره د قانوني ټیټ حد تر رسېدو مه انتظار کوئ.","question":"د سپرلۍ موټر د ټایر د نقش لږ تر لږه قانوني ژوروالی څومره دی؟","options":["1,0 ملي‌متره","1,6 ملي‌متره","2,5 ملي‌متره"],"explanation":"د سپرلۍ موټر د ټایر د نقش قانوني ژوروالی لږ تر لږه 1,6 ملي‌متره دی."},{"n":4,"nl":"Bandenspanning","title":"د ټایرونو د هوا فشار","summary":"د ټایرونو سم فشار د سړک نیول، بریک، د ټایرونو سایېدل او د سون‌توکو مصرف ښه کوي.","rule":"د موټر د جوړوونکي سپارښتل شوی فشار وکاروئ او د دروند بار پر مهال یې د اړتیا له مخې برابر کړئ.","tip":"غوره ده فشار هغه وخت وګورئ چې ټایرونه یخ وي؛ که اضافي ټایر لرئ، هغه هم مه هېروئ.","question":"د ټایرونو فشار په کوم وخت کې تر ټولو باوري اندازه کولای شئ؟","options":["کله چې ټایرونه یخ وي","پر لویه چټکه لاره له اوږد سفر سمدستي وروسته","یوازې کله چې ټایر په ښکاره کم‌هوا وي"],"explanation":"د یخو ټایرونو اندازه د سپارښتل شوي فشار سره تر ټولو ښه سمون لري."},{"n":5,"nl":"Veiligheidsgordel","title":"د خوندیتوب کمربند","summary":"هر څوک شته کمربند کاروي؛ کمربند باید هوار او پر بدن سم نښتی وي.","rule":"چلوونکی او سپرلۍ د سفر پر مهال کمربند تړي، حتی په شا څوکۍ او لنډو سفرونو کې.","tip":"د اوږې پټه پر اوږه او سینه تېره کړئ، نه د شا له خوا یا د لاس لاندې.","question":"څوک باید شته د خوندیتوب کمربند وکاروي؟","options":["یوازې چلوونکی","یوازې مخکینۍ سپرلۍ","هر څوک چې په کمربند لرونکې څوکۍ ناست وي"],"explanation":"هره سپرلۍ شته کمربند کاروي؛ د ماشومانو لپاره نور مقررات هم شته."},{"n":6,"nl":"Kinderzitje","title":"د ماشوم خوندي څوکۍ","summary":"هغه ماشوم چې قد یې له 1,35 متره کم وي، په عمومي قاعده کې په مناسب او منظور شوي ماشوم ساتونکي سیستم کې کښېني.","rule":"د ماشوم د قد او وزن سره مناسبه څوکۍ وټاکئ او د لارښوونو سره سم یې نصب کړئ.","tip":"شا ته مخامخ د ماشوم څوکۍ هېڅکله د فعال مخکیني ایربګ مخې ته مه ږدئ.","question":"له 1,35 متره ټیټ ماشوم عموماً څنګه په سپرلۍ موټر کې لېږدوئ؟","options":["پر شا څوکۍ بې له تړلو","یوازې د لویانو په کمربند سره","په مناسبه او منظور شوې ماشوم څوکۍ کې"],"explanation":"له 1,35 متره ټیټو ماشومانو لپاره په عمومي قاعده کې مناسب او منظور شوی ماشوم ساتونکی سیستم لازمي دی."},{"n":7,"nl":"Spiegels en dode hoek","title":"هندارې او نه لیدل کېدونکې ساحه","summary":"هندارې نه لیدل کېدونکې ساحه کموي، خو په بشپړ ډول یې نه له منځه وړي.","rule":"له تګ مخکې هندارې سمې برابرې کړئ او څنګ ته د خوځېدو پر مهال د موټر ترڅنګ په مستقیم ډول هم وګورئ.","tip":"له ځای بدلولو مخکې په ترتیب سره دننه هنداره، بهرنۍ هنداره، د لوري اشاره او نه لیدل کېدونکې ساحه وګورئ.","question":"ولې پر هندارو سربېره نه لیدل کېدونکې ساحه هم ګورئ؟","options":["ځکه هندارې د موټر ترڅنګ هر څه نه ښيي","ځکه د لوري اشاره کول منع دي","د سرعت لوستلو لپاره"],"explanation":"یو بایسکل، موټرسایکل یا موټر ښايي د هندارو له لید بهر په نه لیدل کېدونکې ساحه کې روان وي."},{"n":8,"nl":"Verlichting","title":"د موټر څراغونه","summary":"په تیاره کې او د ورځې هغه وخت ټیټ څراغ وکاروئ چې لید ډېر کم شوی وي.","rule":"له تګ مخکې وګورئ چې ټیټ، شا، بریک او د لوري څراغونه کار کوي او پاک دي.","tip":"د ورځې څراغونه په هر موټر کې په اتومات ډول د شا څراغونه نه بلوي.","question":"ټیټ څراغ کله لازمي دی؟","options":["یوازې په تونلونو کې","په تیاره کې او د ډېر کم لید پر مهال","یوازې له ابادې سیمې بهر"],"explanation":"ټیټ څراغ په تیاره کې او د ورځې د ډېر کم لید پر مهال لازمي دی."},{"n":9,"nl":"Koelvloeistof","title":"د انجن سړوونکې مایع","summary":"د ګرم انجن د سړولو سیستم هېڅکله مه پرانیزئ؛ ګرمه مایع او بخار د سختو سوځېدو لامل کېدای شي.","rule":"سړوونکې مایع یوازې د لارښود له مخې او د انجن له کافي سړېدو وروسته وګورئ.","tip":"که د تودوخې خبرداری بل شي، خوندي ودرېږئ او انجن سړېدو ته پرېږدئ؛ سرپوښ سمدستي مه پرانیزئ.","question":"انجن ډېر ګرم شوی دی. ایا د سړوونکې مایع د ټانک سرپوښ سمدستي پرانیستلای شئ؟","options":["هو، که دستکشې واغوندئ","نه، لومړی یې په خوندي ډول سړېدو ته پرېږدئ","یوازې د چالان انجن پر مهال"],"explanation":"د ګرم انجن د سړولو سیستم تر فشار لاندې وي؛ پرانیستل یې ګرمه مایع او بخار بهر خوشې کولای شي."},{"n":10,"nl":"Veilige voertuigcontrole","title":"د موټر د خوندیتوب کتنه","summary":"له تګ مخکې لنډه کتنه مخه نیسي چې له ښکاره ناامن عیب سره موټر وچلوئ.","rule":"ټایرونه، څراغونه، ښیښې، هندارې، د مایعاتو خبرداري، د بار ټینګوالی او د دروازو خوندیتوب وګورئ.","tip":"که شک لرئ، د موټر شاوخوا وګرځئ او د سفر له پیل مخکې د خوندیتوب ستونزه حل کړئ.","question":"له تګ مخکې د خوندیتوب په کتنه کې څه شامل دي؟","options":["د ټایرونو، څراغونو، ښیښو او هندارو کتل","یوازې د راډیو برابرول","انجن سمدستي په لوړو دورو چالانول"],"explanation":"د لید، ټایرونو او څراغونو کتنه له تګ مخکې د ښکاره ناامنو عیبونو په موندلو کې مرسته کوي."}]$ps$::jsonb)
AS t(n int,nl text,title text,summary text,rule text,tip text,question text,options jsonb,explanation text);
DO $check$
BEGIN
 IF (SELECT count(*) FROM course_lessons l JOIN content_releases r ON r.id=l.release_id
 JOIN mt_pashto_module_01 t ON t.n=l.lesson_number AND t.nl=l.title->>'nl'
 WHERE r.status='published' AND l.published
 AND (SELECT count(*) FROM jsonb_array_elements(l.content_blocks) b WHERE b->>'type' IN ('rule','exam_tip','quiz'))=3
 AND (SELECT jsonb_array_length(b->'options') FROM jsonb_array_elements(l.content_blocks) b WHERE b->>'type'='quiz')=3) <> 10
 THEN RAISE EXCEPTION 'Pashto source mismatch: expected ten lessons with one rule, tip and three-option quiz'; END IF;
END $check$;
UPDATE course_lessons l SET
 title=l.title||jsonb_build_object('ps',t.title),
 summary=l.summary||jsonb_build_object('ps',t.summary),
 content_blocks=(
 SELECT jsonb_agg(CASE b->>'type'
 WHEN 'rule' THEN jsonb_set(b,'{text}',coalesce(b->'text','{}')||jsonb_build_object('ps',t.rule))
 WHEN 'exam_tip' THEN jsonb_set(b,'{text}',coalesce(b->'text','{}')||jsonb_build_object('ps',t.tip))
 WHEN 'quiz' THEN b||jsonb_build_object(
 'question',coalesce(b->'question','{}')||jsonb_build_object('ps',t.question),
 'explanation',coalesce(b->'explanation','{}')||jsonb_build_object('ps',t.explanation),
 'options',(SELECT jsonb_agg(o||jsonb_build_object('ps',t.options->>(oi-1)::int) ORDER BY oi) FROM jsonb_array_elements(b->'options') WITH ORDINALITY AS opts(o,oi)))
 ELSE b END ORDER BY bi)
 FROM jsonb_array_elements(l.content_blocks) WITH ORDINALITY AS blocks(b,bi)),
 updated_at=NOW()
FROM mt_pashto_module_01 t,content_releases r
WHERE r.id=l.release_id AND r.status='published' AND l.published
AND l.lesson_number=t.n AND l.title->>'nl'=t.nl;
COMMIT;
SELECT count(*) AS pashto_lessons FROM course_lessons
WHERE published AND nullif(title->>'ps','') IS NOT NULL
AND release_id IN (SELECT id FROM content_releases WHERE status='published');
